<div class="page-heading"><div><span class="eyebrow">Parent · Completed vaccinations</span><h1>Vaccination report</h1><p>Review the previous vaccination status for each registered child.</p></div><button class="button button-secondary" type="button" data-print>Print report</button></div>
<section class="report-list"><?php foreach ($records as $record): ?><article><div class="record-check" aria-hidden="true">✓</div><div><span class="eyebrow"><?= e($record['child_name']) ?></span><h2><?= e($record['vaccine_name']) ?> · <?= e($record['dose_label']) ?></h2><p><?= e($record['disease']) ?></p><dl><div><dt>Vaccinated</dt><dd><?= e(display_date($record['administered_at'], 'd M Y, g:i A')) ?></dd></div><div><dt>Hospital</dt><dd><?= e($record['hospital_name']) ?></dd></div><div><dt>Batch number</dt><dd><?= e($record['batch_number'] ?: 'Not recorded') ?></dd></div><div><dt>Notes</dt><dd><?= e($record['notes'] ?: 'No additional notes') ?></dd></div></dl></div></article><?php endforeach; ?><?php if (!$records): ?><div class="empty-state compact"><span class="empty-icon">○</span><h2>No vaccinations recorded yet</h2><p>Completed vaccinations will appear here after the hospital updates an approved appointment.</p></div><?php endif; ?></section>
